import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        boolean[] visited = new boolean[n + 1];
        int[] adj = new int[n + 1];
        for (int i = 0; i < n; i++) {
            adj[i] = (i * k) % n;
        }

        int pairs = 0;

        for (int i = 1; i < n; i++) {
            if (!visited[i]) {
                dfs(i, adj, visited);
                pairs++;
            }
        }

        long mod = 1000000007;
        if (k == 1) {
            System.out.println(pow(n, n, mod));
        } else {
            System.out.println(pow(n, pairs, mod));
        }
        scanner.close();
    }

    private static void dfs(int start, int[] adj, boolean[] visited) {
        int n = adj.length - 1;
        int n_curr = start;
        do {
            visited[n_curr] = true;
            n_curr = adj[n_curr];
        } while (!visited[n_curr]);
    }

    private static long pow(long base, int exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
